package dev.celerbi.easyfarmersdelightcompat.integration.emi;
import dev.celerbi.easyfarmersdelightcompat.integration.CutterAxeInfo;import dev.emi.emi.api.recipe.EmiRecipe;import dev.emi.emi.api.recipe.EmiRecipeCategory;import dev.emi.emi.api.render.EmiTexture;import dev.emi.emi.api.stack.EmiIngredient;import dev.emi.emi.api.stack.EmiStack;import dev.emi.emi.api.widget.WidgetHolder;import java.util.List;import net.minecraft.resources.ResourceLocation;
public final class CutterAxeEmiRecipe implements EmiRecipe{private final CutterAxeInfo info;private final EmiStack input,output;private final EmiIngredient tool;public CutterAxeEmiRecipe(CutterAxeInfo i){info=i;input=EmiStack.of(i.input());tool=EmiIngredient.of(i.tool());output=EmiStack.of(i.output());}public EmiRecipeCategory getCategory(){return EasyFdEmiPlugin.CUTTER_AXE;}public ResourceLocation getId(){return info.id();}public List<EmiIngredient> getInputs(){return List.of(input,tool);}public List<EmiStack> getOutputs(){return List.of(output);}public int getDisplayWidth(){return 150;}public int getDisplayHeight(){return 58;}public void addWidgets(WidgetHolder w){w.addSlot(input,12,6);w.addSlot(tool,50,6);w.addTexture(EmiTexture.EMPTY_ARROW,78,6);w.addSlot(output,116,6).recipeContext(this);w.addText(info.description(),8,36,0x555555,false);}}
